-- Modify "registration_change" table
-- The backchannel_logout_uri kind (ADR-IAM-009 §5.1, TDD-identity-control-003 1.38.0): the URI before and after, null for none.
ALTER TABLE "identity"."registration_change" ADD COLUMN "previous_backchannel_logout_uri" text NULL, ADD COLUMN "backchannel_logout_uri" text NULL, DROP CONSTRAINT "registration_change_kind_check", ADD CONSTRAINT "registration_change_kind_check" CHECK ((kind = ANY (ARRAY['redirect_uris'::text, 'audience'::text, 'lifetime_class'::text, 'backchannel_logout_uri'::text])) AND ((kind = 'redirect_uris'::text) = ((redirect_uris IS NOT NULL) AND (previous_redirect_uris IS NOT NULL))) AND ((kind = 'audience'::text) = ((audience IS NOT NULL) AND (previous_audience IS NOT NULL))) AND ((kind = 'lifetime_class'::text) = ((lifetime_class IS NOT NULL) AND (previous_lifetime_class IS NOT NULL))) AND ((kind = 'backchannel_logout_uri'::text) = (backchannel_logout_uri IS DISTINCT FROM previous_backchannel_logout_uri))); -- atlas:destructive-approved: widening a CHECK, reviewed 2026-10-09
-- Set comment to table: "registration_change"
COMMENT ON TABLE "identity"."registration_change" IS 'A change to a registration''s redirect URIs, audience, lifetime class or back-channel logout URI, proposed, then applied or decided against. TDD-identity-control-003.';
